import React,{useState} from 'react';import './Projects.css';
const initialRows=[['Skyline Heights', 'Sector 150, Noida', '124 units', '₹95 L – ₹2.4 Cr', 'Active', 'Amit Kumar'], ['Green Valley Plots', 'Greater Noida West', '86 plots', '₹45 L – ₹95 L', 'Active', 'Neha Singh'], ['Orchid Business Hub', 'Sector 62, Noida', '42 units', '₹1.2 – ₹3.8 Cr', 'Launching', 'Rohit Verma']];
const headers=['Project Name', 'Location', 'Units', 'Price Range', 'Status', 'Manager'];
const title='Projects';const entity='Project';
function statusClass(v){const s=String(v).toLowerCase();if(['paid','present','available','active','confirmed','completed','qualified','configured'].some(x=>s.includes(x)))return 'pill green-pill';if(['pending','follow-up','on hold','draft','scheduled','review','upcoming','in progress','new','medium','high'].some(x=>s.includes(x)))return 'pill amber-pill';if(['leave','not connected'].some(x=>s.includes(x)))return 'pill red-pill';return 'pill blue-pill'}
export default function Projects({globalSearch}){const [rows,setRows]=useState(initialRows);const [filter,setFilter]=useState('');const [modal,setModal]=useState(false);const [form,setForm]=useState(['','','','','','']);const visible=rows.filter(r=>r.join(' ').toLowerCase().includes((filter||globalSearch||'').toLowerCase()));function save(e){e.preventDefault();if(!form[0].trim())return;setRows(old=>[[...form.slice(0,headers.length)],...old]);setForm(['','','','','','']);setModal(false)}return <div className="page"><div className="page-heading"><div><small>REAL ESTATE CRM · PROJECTS</small><h1>Projects</h1><p>Track developments, phases and project inventory.</p></div><button className="primary" onClick={()=>setModal(true)}>＋ Add project</button></div><div className="mini-cards"><div><span>▦</span><small>Total records</small><strong>{rows.length+124}</strong></div><div><span>↗</span><small>Active / in progress</small><strong>{rows.length+18}</strong></div><div><span>◷</span><small>Needs attention</small><strong>{rows.length+3}</strong></div></div><section className="panel list-panel"><div className="panel-head list-head"><div><h3>{title} list</h3><p>Sample records · local preview only</p></div><div className="actions"><input className="filter" value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Filter records..."/><button className="secondary" onClick={()=>window.print()}>⇩ Export</button></div></div><div className="table-wrap"><table><thead><tr>{headers.map(h=><th key={h}>{h.toUpperCase()}</th>)}</tr></thead><tbody>{visible.map((row,i)=><tr key={i}>{row.map((cell,j)=><td key={j}>{j===0?<b className="primary-cell">{cell||'—'}</b>:(['Status','Availability','Access','Priority','Action'].includes(headers[j])||['Qualified','Follow-up','Site visit','New','Negotiation','Available','On hold','Booked','Active','Launching','Confirmed','Scheduled','Completed','Pending docs','Upcoming','Pending','Paid','Present','On leave','Draft','In progress','High','Medium','Not connected','Review','Configured'].includes(cell))?<span className={statusClass(cell)}>{cell||'—'}</span>:cell||'—'}</td>)}</tr>)}</tbody></table>{visible.length===0&&<div className="empty">No matching records found.</div>}</div><div className="table-footer">Showing {visible.length} records <span>Prototype · Not connected to database</span></div></section><div className="notice">ⓘ <div><b>Demo workspace</b><p>Records added here stay in this browser session only. Database saving, real authentication, permission enforcement and WhatsApp delivery will be connected later.</p></div></div>{modal&&<div className="backdrop" onClick={()=>setModal(false)}><form className="modal" onSubmit={save} onClick={e=>e.stopPropagation()}><div className="modal-head"><div><h2>Add project</h2><p>Enter the basic details to preview the workflow.</p></div><button type="button" className="close" onClick={()=>setModal(false)}>×</button></div>{headers.map((h,i)=><label key={h}>{h}<input value={form[i]} onChange={e=>setForm(old=>old.map((v,j)=>i===j?e.target.value:v))} placeholder={'Enter '+h.toLowerCase()} /></label>)}<div className="modal-actions"><button type="button" className="secondary" onClick={()=>setModal(false)}>Cancel</button><button className="primary" type="submit">Save demo record</button></div><p className="modal-note">Demo only: no server/database is connected.</p></form></div>}</div>}
